class Solution:
    def findMaximumXOR(self, nums: List[int]) -> int:
        max_xor = 0
        mask = 0
        for i in range(31, -1, -1):
            mask |= (1 << i)
            prefixes = set()
            temp_max = max_xor | (1 << i)
            for num in nums:
                prefixes.add(num & mask)
            possible = False
            for prefix in prefixes:
                if (prefix ^ temp_max) in prefixes:
                    possible = True
                    break
            if possible:
                max_xor = temp_max
        return max_xor

